import type { Generated, Insertable, Selectable, Updateable } from "kysely";

/** One cash declaration: "from this moment, I have €30". */
export interface CashBalanceTable {
  /** Generated by Postgres, or the UUID the client generated for the entry. */
  id: Generated<string>;
  userId: string;
  /** A decimal string, zero or more: the cash held from `effectiveAt` onward. */
  amountEur: string;
  effectiveAt: Date;
  /** The member, or the admin editing on their behalf. Empty once that person is deleted. */
  createdBy: string | null;
  createdAt: Generated<Date>;
}

export type CashBalance = Selectable<CashBalanceTable>;
export type NewCashBalance = Insertable<CashBalanceTable>;
export type CashBalanceUpdate = Updateable<CashBalanceTable>;
